def reflect(mirror, x, y):
    if mirror == "x-axis":
        return x, -y
    elif mirror == "y-axis":
        return -x, y
    elif mirror == "y=x":
        return y, x
    else:
        return -y, -x

def rule(mirror):
    if mirror == "x-axis":
        return "keep x, change the sign of y"
    elif mirror == "y-axis":
        return "keep y, change the sign of x"
    elif mirror == "y=x":
        return "swap x and y"
    else:
        return "swap and change both signs"

def show(label, mirror, x, y):
    u, v = reflect(mirror, x, y)
    back = reflect(mirror, u, v)
    print(f"{label}: ({x}, {y}) across {mirror}")
    print(f"  {rule(mirror)}: ({u}, {v})")
    print(f"  check, reflect again: {back}, back where it started: {back == (x, y)}")

show("Example 4", "x-axis", 4, 2)
show("Example 5", "y-axis", -4, 7)
show("Example 6", "y=x", 5, -2)
show("Example 7", "y=-x", 5, -2)
show("Example 8", "y-axis", 0, 6)

