def image(motion, x, y, a, b):
    if motion == "translate":
        return x + a, y + b
    elif motion == "x-axis":
        return x, -y
    elif motion == "y-axis":
        return -x, y
    elif motion == "y=x":
        return y, x
    else:
        return -y, -x

n = int(input())
for i in range(n):
    motion = input()
    x = int(input())
    y = int(input())
    a = 0
    b = 0
    if motion == "translate":
        a = int(input())
        b = int(input())
    u, v = image(motion, x, y, a, b)
    print(f"{motion}: ({x}, {y}) -> ({u}, {v})")

