def move(name, x, y):
    if name == "R90":
        return -y, x
    elif name == "R180":
        return -x, -y
    elif name == "R270":
        return y, -x
    elif name == "x-axis":
        return x, -y
    elif name == "y-axis":
        return -x, y
    elif name == "y=x":
        return y, x
    else:
        return -y, -x

def chain(label, names, x, y):
    print(f"{label}: start at ({x}, {y})")
    for name in names:
        x, y = move(name, x, y)
        print(f"  {name}: ({x}, {y})")
    print(f"  end: ({x}, {y})")

chain("Example 1", ["x-axis", "y=x"], 3, 1)
chain("Example 2", ["y=x", "x-axis"], 3, 1)
chain("Example 5", ["R90", "R270"], 3, 1)
